<template>
  <div class="page-heading"><div><h1 class="page-title">推广数据同步设置</h1><p>设置平台同步开关和报表接口。系统每天北京时间 10:00 同步前一天，14:00 和 22:00 同步当天；归档数据不会被覆盖。</p></div></div>
  <el-alert class="notice" type="info" :closable="false" show-icon><template #title>业务单元授权更新后，腾讯确认可访问的账户共用一份令牌；未通过校验的账户仍使用各自的账户凭证。令牌只在服务端加密保存。</template></el-alert>
  <div class="mapping-panel"><strong>腾讯营销字段对应</strong><div class="mapping-grid"><div><span>管理后台：消费</span><b>腾讯后台：花费</b></div><div><span>管理后台：展现</span><b>腾讯后台：曝光次数</b></div><div><span>管理后台：点击</span><b>腾讯后台：点击次数</b></div><div><span>管理后台：总表单</span><b>腾讯后台：目标转化量</b></div><div><span>管理后台：有效表单</span><b>腾讯后台：有效线索次数</b></div></div></div>
  <div class="cards" v-loading="loading"><el-card v-for="item in configs" :key="item.provider"><template #header><div class="card-title"><span>{{ providerName(item.provider) }}</span><el-tag :type="item.enabled?'success':'info'">{{ item.enabled?'已启用':'未启用' }}</el-tag></div></template><el-form :model="forms[item.provider]" label-width="112px"><el-form-item label="授权状态"><el-tag :type="hasCredentials(item)?'success':'warning'">{{hasCredentials(item)?'凭证已配置':'未配置凭证'}}</el-tag><span v-if="item.provider==='TENCENT_ADS'" class="credential-hint">通过校验的账户共用业务单元授权</span><span v-else class="credential-hint">账户级授权</span></el-form-item><el-form-item label="启用自动同步"><el-switch v-model="forms[item.provider].enabled"/></el-form-item><el-form-item label="日报接口地址" required><el-input v-model="forms[item.provider].reportUrl"/></el-form-item><el-form-item label="最近同步"><span>{{ item.lastSyncedAt?new Date(item.lastSyncedAt).toLocaleString('zh-CN'):'尚未同步' }}</span></el-form-item><el-form-item v-if="item.lastSyncMessage" label="同步结果"><span class="sync-message">{{item.lastSyncMessage}}</span></el-form-item><el-form-item><div class="form-actions"><el-button type="primary" :loading="saving===item.provider" @click="save(item.provider)">保存设置</el-button><el-button :loading="testing===item.provider" @click="saveAndTest(item.provider)">保存并测试昨天</el-button></div></el-form-item></el-form></el-card></div>
  <el-card v-if="isAdministrator" class="shared-auth"><template #header><div class="card-title"><strong>腾讯业务单元授权</strong><el-button type="primary" @click="sharedDialogVisible=true">更新授权</el-button></div></template>
    <div v-if="sharedStatus" class="shared-status"><el-tag :type="sharedStatus.hasAccessToken&&sharedStatus.hasRefreshToken?'success':'warning'">{{ sharedStatus.hasAccessToken&&sharedStatus.hasRefreshToken?'已配置':'未完整配置' }}</el-tag><span>已覆盖 {{ sharedStatus.accounts.filter(account=>account.covered).length }} 个账户</span><span v-if="sharedStatus.updatedAt">更新于 {{ new Date(sharedStatus.updatedAt).toLocaleString('zh-CN') }}</span></div>
    <div v-if="sharedStatus" class="shared-accounts"><span v-for="account in sharedStatus.accounts" :key="account.id" :class="{covered:account.covered}">{{ account.name }} · {{ account.covered?'共用':'未覆盖' }}</span></div>
    <div v-if="sharedResult?.rejected.length" class="shared-rejected">未通过腾讯访问校验：{{ sharedResult.rejected.map(item=>item.name).join('、') }}</div>
  </el-card>
  <el-dialog v-model="sharedDialogVisible" title="更新腾讯业务单元授权" width="600px" destroy-on-close>
    <p>填写同一次腾讯业务单元授权取得的四项凭证。保存前将逐户只读校验；通过的账户共用并自动更新令牌。</p>
    <el-form label-position="top" class="shared-form"><el-form-item label="应用 ID"><el-input v-model="sharedForm.clientId" autocomplete="off" /></el-form-item><el-form-item label="Client Secret"><el-input v-model="sharedForm.clientSecret" type="password" show-password autocomplete="new-password" /></el-form-item><el-form-item label="Access Token"><el-input v-model="sharedForm.accessToken" type="password" show-password autocomplete="new-password" /></el-form-item><el-form-item label="Refresh Token"><el-input v-model="sharedForm.refreshToken" type="password" show-password autocomplete="new-password" /></el-form-item></el-form>
    <template #footer><el-button @click="sharedDialogVisible=false">取消</el-button><el-button type="primary" :loading="sharedSaving" @click="saveSharedAuthorization">校验并保存</el-button></template>
  </el-dialog>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { getPromotionSyncConfigs, getTencentBusinessUnitCredential, syncPromotionDailyMetrics, type PromotionDataSyncConfigItem, type TencentBusinessUnitCredentialResult, type TencentBusinessUnitCredentialStatus, updatePromotionSyncConfig, updateTencentBusinessUnitCredential } from '../api/admin';
import { useAuthStore } from '../stores/auth';
type Provider='TENCENT_ADS'|'OCEANENGINE';
const configs=ref<PromotionDataSyncConfigItem[]>([]);const loading=ref(false);const saving=ref('');const testing=ref('');const forms=reactive<Record<string,{enabled:boolean;reportUrl:string}>>({});
const authStore=useAuthStore();
const isAdministrator=computed(()=>['SUPER_ADMIN','MANAGER'].includes(authStore.user?.role||''));
const sharedStatus=ref<TencentBusinessUnitCredentialStatus>();
const sharedResult=ref<TencentBusinessUnitCredentialResult>();
const sharedDialogVisible=ref(false);const sharedSaving=ref(false);
const sharedForm=reactive({clientId:'',clientSecret:'',accessToken:'',refreshToken:''});
const providerName=(provider:string)=>provider==='TENCENT_ADS'?'腾讯营销':'巨量引擎';
const hasCredentials=(item:PromotionDataSyncConfigItem)=>Boolean(item.hasAccessToken||(item.clientId&&item.hasClientSecret&&item.hasRefreshToken));
async function load(){loading.value=true;try{configs.value=await getPromotionSyncConfigs();for(const item of configs.value)forms[item.provider]={enabled:item.enabled,reportUrl:item.reportUrl};if(isAdministrator.value)sharedStatus.value=await getTencentBusinessUnitCredential()}finally{loading.value=false}}
async function saveSharedAuthorization(){if(Object.values(sharedForm).some(value=>!value.trim()))return ElMessage.warning('请完整填写四项授权凭证');sharedSaving.value=true;try{sharedResult.value=await updateTencentBusinessUnitCredential({...sharedForm});Object.assign(sharedForm,{clientId:'',clientSecret:'',accessToken:'',refreshToken:''});sharedDialogVisible.value=false;ElMessage.success(`业务单元授权已更新，覆盖 ${sharedResult.value.covered.length} 个账户`);await load()}finally{sharedSaving.value=false}}
async function save(provider:Provider,quiet=false){const form=forms[provider];if(!form.reportUrl.trim())return ElMessage.warning('请填写日报接口地址');saving.value=provider;try{await updatePromotionSyncConfig({provider,...form});if(!quiet)ElMessage.success('同步设置已保存');await load()}finally{saving.value=''}}
async function saveAndTest(provider:Provider){const form=forms[provider];if(!form.reportUrl.trim())return ElMessage.warning('请填写日报接口地址');if(!form.enabled)return ElMessage.warning('请先开启自动同步');testing.value=provider;try{await save(provider,true);const date=new Date();date.setDate(date.getDate()-1);const statDate=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const current=(await syncPromotionDailyMetrics({statDate,provider}))[0];if(current?.errors.length)ElMessage.error(current.errors.join('；'));else if(current?.noData)ElMessage.warning(`同步完成：成功 ${current.synced} 个账户，平台无数据 ${current.noData} 个账户`);else ElMessage.success(`测试成功，已同步 ${current?.synced||0} 个账户`);await load()}finally{testing.value=''}}
onMounted(load);
</script>
<style scoped>.page-heading{margin-bottom:18px}.page-title{margin:0 0 6px}.page-heading p{margin:0;color:var(--admin-text-muted)}.notice{margin-bottom:14px}.mapping-panel{margin-bottom:18px;padding:14px 16px;border:1px solid var(--admin-border);border-radius:12px;background:var(--el-fill-color-lighter)}.mapping-panel>strong{display:block;margin-bottom:10px;color:var(--admin-text)}.mapping-grid{display:grid;grid-template-columns:repeat(5,minmax(150px,1fr));gap:8px}.mapping-grid span,.mapping-grid b{display:block;padding:7px 9px;border-radius:7px;font-size:12px}.mapping-grid span{padding-bottom:2px;color:var(--admin-text-muted)}.mapping-grid b{padding-top:2px;color:var(--el-color-primary);font-weight:650}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(440px,1fr));gap:18px}.card-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.form-actions{display:flex;gap:10px;flex-wrap:wrap}.form-actions :deep(.el-button){margin:0}.sync-message{line-height:1.7;color:var(--admin-text-muted)}.credential-hint{margin-left:10px;color:var(--admin-text-muted);font-size:12px}.shared-auth{margin-top:18px}.shared-status,.shared-accounts{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.shared-accounts{margin-top:12px}.shared-accounts span{padding:6px 10px;border-radius:8px;background:var(--el-fill-color-light);color:var(--admin-text-muted)}.shared-accounts span.covered{color:var(--el-color-success)}.shared-rejected{margin-top:12px;color:var(--el-color-danger);overflow-wrap:anywhere}.shared-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px}.shared-form :deep(.el-form-item){min-width:0}@media(max-width:900px){.mapping-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.cards{grid-template-columns:1fr}.mapping-grid,.shared-form{grid-template-columns:1fr}.form-actions{display:grid;grid-template-columns:1fr;width:100%}.form-actions :deep(.el-button){width:100%}.card-title{flex-wrap:wrap}}</style>
